/* audio/limiter.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function makeLimiterCurve(mode) {
    const samples = 4096;
    const curve = new Float32Array(samples);
    for (let i = 0; i < samples; i++) {
      const x = (i / (samples - 1)) * 2 - 1;
      if (mode === "truepeak") curve[i] = (Math.tanh(x * 1.6) / Math.tanh(1.6)) * 0.96;
      else if (mode === "softclip") curve[i] = (Math.tanh(x * 1.3) / Math.tanh(1.3)) * 0.99;
      else curve[i] = P.clamp(x, -0.999, 0.999);
    }
    return curve;
  }

  function stopLimiterChain() {
    P.limiterChainNodes.forEach((node) => { try { node.disconnect(); } catch {} });
    P.limiterChainNodes = [];
    P.limiterNode = null;
    P.limiterInputNode = null;
    P.limiterOutputNode = null;
  }

  // Four ceiling modes. dBFS uses a compressor, true peak adds 4× oversampling
  // and intersample headroom, and the clip modes use WaveShaper curves.
  function ensureLimiter() {
    const context = P.sharedAudioContext();
    if (!context) return null;
    if (P.limiterInputNode && P.limiterOutputNode) return P.limiterInputNode;
    P.stopLimiterChain();
    try {
      const input = context.createGain();
      const output = context.createGain();
      const keep = (node) => { P.limiterChainNodes.push(node); return node; };
      let tail = input;
      const mode = P.LIMITER_MODES.includes(P.state.limiterMode) ? P.state.limiterMode : "dbfs";

      if (mode === "dbfs" || mode === "truepeak") {
        const comp = keep(context.createDynamicsCompressor());
        comp.threshold.value = mode === "truepeak" ? -2.5 : -1;
        comp.knee.value = 0;
        comp.ratio.value = 20;
        comp.attack.value = mode === "truepeak" ? 0.001 : 0.003;
        comp.release.value = mode === "truepeak" ? 0.18 : 0.25;
        tail.connect(comp);
        tail = comp;
        P.limiterNode = comp;
        if (mode === "truepeak") {
          const shaper = keep(context.createWaveShaper());
          shaper.curve = P.makeLimiterCurve("truepeak");
          try { shaper.oversample = "4x"; } catch {}
          tail.connect(shaper);
          tail = shaper;
          P.limiterNode = shaper;
        }
      } else {
        const shaper = keep(context.createWaveShaper());
        shaper.curve = P.makeLimiterCurve(mode);
        try { shaper.oversample = mode === "softclip" ? "4x" : "none"; } catch {}
        tail.connect(shaper);
        tail = shaper;
        P.limiterNode = shaper;
      }
      tail.connect(output);
      P.limiterInputNode = input;
      P.limiterOutputNode = output;
      return input;
    } catch {
      P.stopLimiterChain();
      return null;
    }
  }

  function rebuildLimiter() {
    P.stopLimiterChain();
    P.ensureLimiter();
    P.wireMasterOutput();
  }

  function setLimiterMode(mode) {
    if (!P.LIMITER_MODES.includes(mode) || mode === P.state.limiterMode) return;
    P.state.limiterMode = mode;
    P.rebuildLimiter();
    P.connectMainOutput();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function ensureLimiterMeter() {
    const context = P.sharedAudioContext();
    if (!context) return null;
    if (P.limiterMeterNode) return P.limiterMeterNode;
    try {
      const analyser = context.createAnalyser();
      analyser.fftSize = 2048;
      analyser.smoothingTimeConstant = 0.6;
      P.limiterMeterNode = analyser;
    } catch {
      P.limiterMeterNode = null;
    }
    return P.limiterMeterNode;
  }

  function ensureMasterOutput() {
    const context = P.sharedAudioContext();
    if (!context) return null;
    if (P.masterOutputNode) {
      P.wireMasterOutput();
      return P.masterOutputNode;
    }
    try {
      P.masterOutputNode = context.createGain();
      P.masterOutputNode.gain.value = 1;
      P.wireMasterOutput();
    } catch {
      P.masterOutputNode = null;
    }
    return P.masterOutputNode;
  }

  function wireMasterOutput() {
    if (!P.masterOutputNode || !P.audioContext) return;
    try { P.masterOutputNode.disconnect(); } catch {}
    const meter = P.ensureLimiterMeter();
    if (P.limiterEnabled) {
      const input = P.ensureLimiter();
      if (input && P.limiterOutputNode) {
        try { P.limiterOutputNode.disconnect(); } catch {}
        try { P.masterOutputNode.connect(input); } catch {}
        if (meter) {
          try { P.limiterOutputNode.connect(meter); } catch {}
        }
        try { P.limiterOutputNode.connect(P.audioContext.destination); } catch {}
        return;
      }
    }
    if (meter) {
      try { P.masterOutputNode.connect(meter); } catch {}
    }
    try { P.masterOutputNode.connect(P.audioContext.destination); } catch {}
  }

  function outputDestination() {
    if (!P.audioContext) return null;
    return P.ensureMasterOutput() || P.audioContext.destination;
  }

  function connectMainOutput() {
    if (!P.mainGainNode || !P.audioContext) return;
    try { P.mainGainNode.disconnect(); } catch {}
    const fxInput = P.liveFxActive() ? P.ensureLiveFx() : null;
    if (!fxInput) P.stopLiveFx();
    const target = fxInput || (P.state.eqEnabled && P.eqInputNode ? P.eqInputNode : P.outputDestination());
    try { P.mainGainNode.connect(target); } catch {}
  }
  Object.assign(P, { makeLimiterCurve, stopLimiterChain, ensureLimiter, rebuildLimiter, setLimiterMode, ensureLimiterMeter, ensureMasterOutput, wireMasterOutput, outputDestination, connectMainOutput });
}
